import java.io.*;

public class Main {
    static int n;
    static int[] height;
    static boolean[][] connected;
    static int[] memo;

    static int longestPath(int room) {
        if (memo[room] != -1) return memo[room];

        int best = 0;
        for (int next = 0; next < n; next++) {
            if (connected[room][next] && height[room] > height[next]) {
                best = Math.max(best, 1 + longestPath(next));
            }
        }
        return memo[room] = best;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        int tunnels = fs.nextInt();
        int start = fs.nextInt() - 1;

        height = new int[n];
        for (int i = 0; i < n; i++) height[i] = fs.nextInt();

        connected = new boolean[n][n];
        for (int i = 0; i < tunnels; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            connected[a][b] = connected[b][a] = true;
        }

        memo = new int[n];
        java.util.Arrays.fill(memo, -1);

        System.out.println(longestPath(start));
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }
}
